import React, { useRef, useState, useMemo, useEffect, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Text } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.2;

// --- Helper: Math ---
const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return p.distanceToSquared(v.clone().add(w.clone().sub(v).multiplyScalar(t)));
};

const distToSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    return Math.sqrt(distToSegmentSquared(p, v, w));
};

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[], holes?: IPoint[][]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  shape.moveTo(points[0].x, points[0].z); 
  for (let i = 1; i < points.length; i++) {
      shape.lineTo(points[i].x, points[i].z);
  }
  shape.closePath();

  if (holes && holes.length > 0) {
      holes.forEach(holePoints => {
          if (holePoints.length > 0) {
              const holePath = new THREE.Path();
              holePath.moveTo(holePoints[0].x, holePoints[0].z);
              for (let i = 1; i < holePoints.length; i++) {
                  holePath.lineTo(holePoints[i].x, holePoints[i].z);
              }
              holePath.closePath();
              shape.holes.push(holePath);
          }
      });
  }

  return shape;
};

// --- Sub-Component: Shape Renderer ---
const ShapeRenderer: React.FC<{ shape: IShape; isSelected: boolean }> = React.memo(({ shape, isSelected }) => {
    const { updateShape, selectShape, tool } = useApp();

    // Geometry memoization
    const geometry = useMemo(() => {
        if (shape.type === 'line' || shape.type === 'dimension') return null; // Handled separately

        const threeShape = createThreeShape(shape.points, shape.holes);

        if (shape.type === 'flat') {
            return new THREE.ShapeGeometry(threeShape);
        }

        // Solid
        return new THREE.ExtrudeGeometry(threeShape, {
            depth: shape.height || DEFAULT_HEIGHT,
            bevelEnabled: false,
        });
    }, [shape.points, shape.holes, shape.height, shape.type]);

    // Position & Rotation adjustments
    // Note: ExtrudeGeometry extrudes along Z by default, we usually rotate X to make it stand up, 
    // or we draw shape on XZ plane. Here we assumed XZ drawing in createThreeShape (y -> z).
    // Extrude creates volume along Z axis of the 2D shape. 
    // If we draw on XZ (Top down), the 2D shape coordinates are X, Y(mapped to Z).
    // Extrude depth adds to the 3rd dimension (Z local). 
    // We need to rotate the mesh to align correctly if needed. 
    // Let's assume standard logic: Shape is on XZ plane, Height is Y.

    const euler = useMemo(() => new THREE.Euler(...shape.rotation), [shape.rotation]);
    const position = useMemo(() => new THREE.Vector3(...shape.position), [shape.position]);

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE) {
            e.stopPropagation();
            selectShape(shape.id, e.shiftKey);
        }
    };

    if (shape.type === 'text') {
        return (
            <group position={position} rotation={euler} scale={shape.scale}>
                <Text
                    position={[0, shape.height + 0.02, 0]}
                    rotation={[-Math.PI / 2, 0, 0]} // Face up by default
                    fontSize={shape.fontSize || 0.5}
                    color={shape.color}
                    anchorX="center"
                    anchorY="middle"
                    onClick={handleClick}
                >
                    {shape.content || shape.name}
                </Text>
                {/* Invisible plane for easier selection */}
                <mesh rotation={[-Math.PI / 2, 0, 0]} onClick={handleClick} visible={false}>
                    <planeGeometry args={[shape.points[1].x - shape.points[0].x, shape.points[2].z - shape.points[0].z]} />
                </mesh>
            </group>
        );
    }

    if (shape.type === 'line') {
        // Simple line implementation
        const points = shape.points.map(p => new THREE.Vector3(p.x, 0, p.z));
        points.push(points[0]); // Close loop for now
        return (
            <group position={position} rotation={euler} scale={shape.scale}>
                <line>
                    <bufferGeometry>
                        <float32BufferAttribute attach="attributes-position" count={points.length} array={new Float32Array(points.flatMap(p => [p.x, p.y, p.z]))} itemSize={3} />
                    </bufferGeometry>
                    <lineBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} linewidth={2} />
                </line>
                {/* Hit area */}
                 <mesh onClick={handleClick} visible={false}>
                     {/* Bounding box hit area approximation could go here */}
                     <boxGeometry args={[1, 0.1, 1]} /> 
                 </mesh>
            </group>
        );
    }

    if (!geometry) return null;

    // For extruded shapes, we need to rotate -90 deg on X if we generated Shape on XY plane to simulate XZ.
    // However, our createThreeShape maps input Z to shape Y. 
    // ExtrudeGeometry extrudes along Z. 
    // So (x, z_input) -> (x, y_shape). Extrude -> (x, y_shape, z_depth).
    // We want (x, z, y_height).
    // So we rotate X by 90 degrees.

    return (
        <group position={position} rotation={euler} scale={shape.scale}>
            <mesh 
                geometry={geometry} 
                onClick={handleClick}
                rotation={[Math.PI / 2, 0, 0]} // Align extrusion to Y axis
                castShadow
                receiveShadow
            >
                <meshStandardMaterial 
                    color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
                    transparent={shape.type === 'flat'}
                    opacity={shape.type === 'flat' ? 0.5 : 1}
                />
            </mesh>

            {/* Edges */}
            {isSelected && (
                <lineSegments rotation={[Math.PI / 2, 0, 0]}>
                    <edgesGeometry args={[geometry]} />
                    <lineBasicMaterial color="white" />
                </lineSegments>
            )}
        </group>
    );
});

// --- Main Scene Content ---
const SceneContent: React.FC = () => {
    const { 
        shapes, 
        tool, 
        addShape, 
        selectedIds, 
        updateShape, 
        currentView,
        setCurrentView
    } = useApp();

    const { camera, gl } = useThree();

    // Drawing State
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [mousePos, setMousePos] = useState<IPoint | null>(null);

    // --- Interaction Handlers ---
    const handlePlaneClick = (e: ThreeEvent<MouseEvent>) => {
        // Only handle clicks on the ground plane if we are in a drawing tool
        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_TEXT].includes(tool)) {
            return;
        }

        e.stopPropagation();
        const point = { x: e.point.x, y: 0, z: e.point.z };

        // Snap to Grid
        point.x = Math.round(point.x / SNAP_GRID) * SNAP_GRID;
        point.z = Math.round(point.z / SNAP_GRID) * SNAP_GRID;

        if (tool === ToolType.DRAW_TEXT) {
            addShape({
                id: `text-${Date.now()}`,
                type: 'text',
                name: '文字說明',
                content: '點擊編輯文字',
                points: [{x: point.x, y:0, z: point.z}, {x: point.x + 1, y:0, z: point.z + 1}], // Dummy bounds
                height: 0,
                layerId: '', // Context will assign active
                color: '#333333',
                position: [point.x, 0, point.z],
                rotation: [0, 0, 0],
                scale: [1, 1, 1],
                fontSize: 0.5
            });
            return;
        }

        const newPoints = [...drawPoints, point];
        setDrawPoints(newPoints);

        // Finish shape logic
        if (tool === ToolType.DRAW_RECT && newPoints.length === 2) {
             const [p1, p2] = newPoints;
             const rectPoints: IPoint[] = [
                 { x: p1.x, y: 0, z: p1.z },
                 { x: p2.x, y: 0, z: p1.z },
                 { x: p2.x, y: 0, z: p2.z },
                 { x: p1.x, y: 0, z: p2.z },
                 { x: p1.x, y: 0, z: p1.z } // Close
             ];
             createShape(rectPoints, 'solid');
             setDrawPoints([]);
        } else if (tool === ToolType.DRAW_CIRCLE && newPoints.length === 2) {
            const [center, edge] = newPoints;
            const radius = Math.sqrt(Math.pow(edge.x - center.x, 2) + Math.pow(edge.z - center.z, 2));
            const circlePoints: IPoint[] = [];
            const segs = 32;
            for(let i=0; i<=segs; i++) {
                const theta = (i/segs) * Math.PI * 2;
                circlePoints.push({
                    x: Math.cos(theta) * radius,
                    y: 0,
                    z: Math.sin(theta) * radius
                });
            }
            createShape(circlePoints, 'solid', center);
            setDrawPoints([]);
        } else if (tool === ToolType.DRAW_LINE && newPoints.length > 2) {
            // Check if closed
            const first = newPoints[0];
            const last = newPoints[newPoints.length - 1];
            const dist = Math.sqrt(Math.pow(first.x - last.x, 2) + Math.pow(first.z - last.z, 2));
            if (dist < 0.2) {
                // Close loop
                newPoints.pop(); // Remove last click which was near start
                newPoints.push(first);
                createShape(newPoints, 'solid');
                setDrawPoints([]);
            }
        }
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE].includes(tool)) return;

        const x = Math.round(e.point.x / SNAP_GRID) * SNAP_GRID;
        const z = Math.round(e.point.z / SNAP_GRID) * SNAP_GRID;
        setMousePos({ x, y: 0, z });
    };

    const createShape = (points: IPoint[], type: ShapeType, offset?: IPoint) => {
        // Calculate center to normalize position
        let minX = Infinity, minZ = Infinity, maxX = -Infinity, maxZ = -Infinity;
        points.forEach(p => {
            minX = Math.min(minX, p.x);
            maxX = Math.max(maxX, p.x);
            minZ = Math.min(minZ, p.z);
            maxZ = Math.max(maxZ, p.z);
        });

        const centerX = offset ? offset.x : (minX + maxX) / 2;
        const centerZ = offset ? offset.z : (minZ + maxZ) / 2;

        // Localize points
        const localPoints = points.map(p => ({
            x: p.x - (offset ? 0 : centerX), // If circle (offset provided), keep relative to center 0
            y: 0,
            z: p.z - (offset ? 0 : centerZ)
        }));

        addShape({
            id: `shape-${Date.now()}`,
            type,
            name: type === 'solid' ? '未命名物體' : '平面',
            points: localPoints,
            height: type === 'solid' ? 1.0 : DEFAULT_HEIGHT, // Default 1m height
            layerId: '',
            color: type === 'solid' ? DEFAULT_COLOR : '#cbd5e1',
            position: [centerX, 0, centerZ],
            rotation: [0, 0, 0],
            scale: [1, 1, 1]
        });
    };

    // --- View Updates ---
    useEffect(() => {
        if (!currentView) return;

        const dist = 20;
        const pos = new THREE.Vector3();

        switch(currentView) {
            case 'top': pos.set(0, dist, 0); break;
            case 'front': pos.set(0, 0, dist); break;
            case 'left': pos.set(-dist, 0, 0); break;
            case 'right': pos.set(dist, 0, 0); break;
            case 'bottom': pos.set(0, -dist, 0); break;
        }

        // Animate camera
        // Note: For simplicity in this specialized prompt, we snap. 
        // Real implementation usually uses TWEEN or camera.position.lerp in useFrame
        camera.position.copy(pos);
        camera.lookAt(0, 0, 0);
        setCurrentView(null); // Reset trigger
    }, [currentView, camera, setCurrentView]);


    return (
        <>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />

            <Grid 
                args={[100, 100]} 
                cellSize={1} 
                cellThickness={0.5} 
                cellColor="#cbd5e1" 
                sectionSize={5} 
                sectionThickness={1}
                sectionColor="#94a3b8"
                fadeDistance={50}
                infiniteGrid 
            />

            {/* Render Shapes */}
            {shapes.map(shape => (
                <ShapeRenderer 
                    key={shape.id} 
                    shape={shape} 
                    isSelected={selectedIds.includes(shape.id)} 
                />
            ))}

            {/* Drawing Preview */}
            {drawPoints.length > 0 && mousePos && (
                <line>
                    <bufferGeometry>
                        <float32BufferAttribute 
                            attach="attributes-position" 
                            count={2} 
                            array={new Float32Array([
                                drawPoints[drawPoints.length-1].x, 0.1, drawPoints[drawPoints.length-1].z,
                                mousePos.x, 0.1, mousePos.z
                            ])} 
                            itemSize={3} 
                        />
                    </bufferGeometry>
                    <lineBasicMaterial color="red" />
                </line>
            )}

            {/* Interaction Plane */}
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, -0.01, 0]} 
                onClick={handlePlaneClick}
                onPointerMove={handlePointerMove}
            >
                <planeGeometry args={[100, 100]} />
                <meshBasicMaterial visible={false} />
            </mesh>

            {/* Controls */}
            {/* 
               CRITICAL CHANGE: enableRotate is strictly bound to tool === ToolType.HAND 
               Other tools only allow Pan (Right Click usually) and Zoom.
            */}
            <OrbitControls 
                makeDefault
                enableDamping={false}
                enableRotate={tool === ToolType.HAND}
                enablePan={true}
                enableZoom={true}
            />

            {/* Gizmo */}
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" />
            </GizmoHelper>

            {/* Transform Controls for Selection */}
            {selectedIds.length === 1 && tool === ToolType.SELECT && (
                <TransformControls 
                    object={undefined} 
                    attach="object"
                    mode="translate"
                    onDragging-changed={(e) => {
                         // Optional: Disable orbit while dragging gizmo
                    }}
                >
                     {/* We need to attach this to the selected mesh refs usually. 
                         For this simplified rebuild, we skip direct attachment logic 
                         since we need refs from ShapeRenderer which are inside a map.
                         In a full implementation, we'd pass refs up or use a store.
                     */}
                </TransformControls>
            )}
        </>
    );
};

