        );
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const p1 = drawPoints[0];
        const p2 = mousePos;
        const radius = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.z - p1.z, 2));

        const segments = 64;
        const circleVertices = [];
        for (let i = 0; i <= segments; i++) {
            const theta = (i / segments) * Math.PI * 2;
            circleVertices.push(p1.x + radius * Math.cos(theta));
            circleVertices.push(0.1);
            circleVertices.push(p1.z + radius * Math.sin(theta));
        }

        return (
            <group>
                 <line>
                    <bufferGeometry>
                        <float32BufferAttribute attach="attributes-position" count={2} array={new Float32Array([p1.x, 0.1, p1.z, p2.x, 0.1, p2.z])} itemSize={3} />
                    </bufferGeometry>
                    <lineBasicMaterial color="red" opacity={0.5} transparent />
                </line>
                <line>
                    <bufferGeometry>
                        <float32BufferAttribute attach="attributes-position" count={segments + 1} array={new Float32Array(circleVertices)} itemSize={3} />
                    </bufferGeometry>
                    <lineBasicMaterial color="red" />
                </line>
            </group>
        );
    }

    if (tool === ToolType.DRAW_LINE) {
        const pathPoints = drawPoints.flatMap(p => [p.x, 0.1, p.z]);
        const last = drawPoints[drawPoints.length - 1];
        const rubberband = [last.x, 0.1, last.z, mousePos.x, 0.1, mousePos.z];

        return (
            <group>
                {drawPoints.length > 1 && (
                     <line>
                        <bufferGeometry>
                            <float32BufferAttribute attach="attributes-position" count={drawPoints.length} array={new Float32Array(pathPoints)} itemSize={3} />
                        </bufferGeometry>
                        <lineBasicMaterial color="red" />
                    </line>
                )}
                <line>
                    <bufferGeometry>
                        <float32BufferAttribute attach="attributes-position" count={2} array={new Float32Array(rubberband)} itemSize={3} />
                    </bufferGeometry>
                    <lineBasicMaterial color="red" />
                </line>
            </group>
        );
    }

    return null;
};

// --- Main Scene Content ---
const SceneContent: React.FC = () => {
    const { 
        shapes, 
        tool, 
        addShape, 
        selectedIds, 
        currentView,
        setCurrentView
    } = useApp();

    const { camera } = useThree();

    // Drawing State
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [mousePos, setMousePos] = useState<IPoint | null>(null);

    // --- Interaction Handlers ---
    const handlePlaneClick = (e: ThreeEvent<MouseEvent>) => {
        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_TEXT].includes(tool)) {
            return;
        }

        e.stopPropagation();
        const point = { x: e.point.x, y: 0, z: e.point.z };

        // Snap to Grid
        point.x = Math.round(point.x / SNAP_GRID) * SNAP_GRID;
        point.z = Math.round(point.z / SNAP_GRID) * SNAP_GRID;

        if (tool === ToolType.DRAW_TEXT) {
            addShape({
                id: `text-${Date.now()}`,
                type: 'text',
                name: '文字說明',
                content: '點擊編輯文字',
                points: [{x: point.x, y:0, z: point.z}, {x: point.x + 1, y:0, z: point.z + 1}],
                height: 0,
                layerId: '', 
                color: '#333333',
                position: [point.x, 0, point.z],
                rotation: [0, 0, 0],
                scale: [1, 1, 1],
                fontSize: 0.5
            });
            return;
        }

        const newPoints = [...drawPoints, point];
        setDrawPoints(newPoints);

        if (tool === ToolType.DRAW_RECT && newPoints.length === 2) {
             const [p1, p2] = newPoints;
             const rectPoints: IPoint[] = [
                 { x: p1.x, y: 0, z: p1.z },
                 { x: p2.x, y: 0, z: p1.z },
                 { x: p2.x, y: 0, z: p2.z },
                 { x: p1.x, y: 0, z: p2.z },
                 { x: p1.x, y: 0, z: p1.z } 
             ];
             createShape(rectPoints, 'solid');
             setDrawPoints([]);
        } else if (tool === ToolType.DRAW_CIRCLE && newPoints.length === 2) {
            const [center, edge] = newPoints;
            const radius = Math.sqrt(Math.pow(edge.x - center.x, 2) + Math.pow(edge.z - center.z, 2));
            const circlePoints: IPoint[] = [];
            const segs = 32;
            for(let i=0; i<=segs; i++) {
                const theta = (i/segs) * Math.PI * 2;
                circlePoints.push({
                    x: Math.cos(theta) * radius,
                    y: 0,
                    z: Math.sin(theta) * radius
                });
            }
            createShape(circlePoints, 'solid', center);
            setDrawPoints([]);
        } else if (tool === ToolType.DRAW_LINE && newPoints.length > 2) {
            const first = newPoints[0];
            const last = newPoints[newPoints.length - 1];
            const dist = Math.sqrt(Math.pow(first.x - last.x, 2) + Math.pow(first.z - last.z, 2));
            if (dist < 0.2) {
                newPoints.pop(); 
                newPoints.push(first);
                createShape(newPoints, 'solid');
                setDrawPoints([]);
            }
        }
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE].includes(tool)) return;

        const x = Math.round(e.point.x / SNAP_GRID) * SNAP_GRID;
        const z = Math.round(e.point.z / SNAP_GRID) * SNAP_GRID;
        setMousePos({ x, y: 0, z });
    };

    const createShape = (points: IPoint[], type: ShapeType, offset?: IPoint) => {
        let minX = Infinity, minZ = Infinity, maxX = -Infinity, maxZ = -Infinity;
        points.forEach(p => {
            minX = Math.min(minX, p.x);
            maxX = Math.max(maxX, p.x);
            minZ = Math.min(minZ, p.z);
            maxZ = Math.max(maxZ, p.z);
        });

        const centerX = offset ? offset.x : (minX + maxX) / 2;
        const centerZ = offset ? offset.z : (minZ + maxZ) / 2;

        const localPoints = points.map(p => ({
            x: p.x - (offset ? 0 : centerX),
            y: 0,
            z: p.z - (offset ? 0 : centerZ)
        }));

        addShape({
            id: `shape-${Date.now()}`,
            type,
            name: type === 'solid' ? '未命名物體' : '平面',
            points: localPoints,
            height: type === 'solid' ? 1.0 : DEFAULT_HEIGHT,
            layerId: '',
            color: type === 'solid' ? DEFAULT_COLOR : '#cbd5e1',
            position: [centerX, 0, centerZ],
            rotation: [0, 0, 0],
            scale: [1, 1, 1]
        });
    };

    useEffect(() => {
        if (!currentView) return;

        const dist = 20;
        const pos = new THREE.Vector3();

        switch(currentView) {
            case 'top': pos.set(0, dist, 0); break;
            case 'front': pos.set(0, 0, dist); break;
            case 'left': pos.set(-dist, 0, 0); break;
            case 'right': pos.set(dist, 0, 0); break;
            case 'bottom': pos.set(0, -dist, 0); break;
        }

        camera.position.copy(pos);
        camera.lookAt(0, 0, 0);
        setCurrentView(null); 
    }, [currentView, camera, setCurrentView]);


    return (
        <>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />

            <Grid 
                args={[100, 100]} 
                cellSize={1} 
                cellThickness={0.5} 
                cellColor="#cbd5e1" 
                sectionSize={5} 
                sectionThickness={1}
                sectionColor="#94a3b8"
                fadeDistance={50}
                infiniteGrid 
            />

            {shapes.map(shape => (
                <ShapeRenderer 
                    key={shape.id} 
                    shape={shape} 
                    isSelected={selectedIds.includes(shape.id)} 
                />
            ))}

            <DrawingPreview drawPoints={drawPoints} mousePos={mousePos} tool={tool} />

            {/* Interaction Plane: Moved to y=0.01 to avoid Z-fighting/Blocking by Grid */}
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.01, 0]} 
                onClick={handlePlaneClick}
                onPointerMove={handlePointerMove}
            >
                <planeGeometry args={[100, 100]} />
                <meshBasicMaterial transparent opacity={0} depthWrite={false} />
            </mesh>

            <OrbitControls 
                makeDefault
                enableDamping={false}
                enableRotate={tool === ToolType.HAND}
                enablePan={true}
                enableZoom={true}
            />

            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" />
            </GizmoHelper>
        </>
    );
};

const Viewport: React.FC = () => {
  return (
    <div className="w-full h-full bg-slate-50 cursor-crosshair">
        <Canvas shadows camera={{ position: [8, 8, 8], fov: 45 }}>
            <SceneContent />
        </Canvas>
    </div>
  );
};

export default Viewport;
